      "content": "{\n  \"name\": \"deepseek-harness-desktop\",\n  \"type\": \"module\",\n  \"version\": \"0.25.0\",\n  \"private\": true,\n  \"packageManager\": \"pnpm@11.7.0\",\n  \"description\": \"Desktop application for DeepSeek Harness (dsh) — one-click local install and launch, no Node.js setup required.\",\n  \"main\": \"./src-native/entry.ts\",\n  \"scripts\": {\n    \"dev\": \"vite\",\n    \"dev:desktop\": \"pnpm dev:plugins & tauri dev\",\n    \"dev:plugins\": \"pnpm --filter \\\"./packages/*\\\" -r --parallel run dev\",\n    \"prebuild\": \"pnpm build:plugins\",\n    \"build\": \"tsc && vite build\",\n    \"build:plugins\": \"tsx scripts/build-plugins.ts\",\n    \"build:taiwindcss\": \"tsx packages/dsh-tauri-ui/scripts/taiwindcss.ts\",\n    \"build:debug\": \"tsx scripts/build-debug.ts\",\n    \"genapi\": \"genapi\",\n    \"preview\": \"vite preview\",\n    \"tauri\": \"tauri\",\n    \"release\": \"bumpp --pr\",\n    \"test\": \"vitest\",\n    \"test:unit\": \"vitest --project unit\",\n    \"test:e2e:plugin\": \"vitest --project plugin\",\n    \"test:e2e:desktop\": \"vitest --project desktop\",\n    \"lint\": \"eslint\",\n    \"lint:fix\": \"eslint . --fix\",\n    \"typecheck\": \"tsc --project tsconfig.typecheck.json --noEmit\",\n    \"icons\": \"tauri icon public/deepseek-harness-desktop-tauri.svg --output src-tauri/icons && tauri icon public/deepseek-harness-desktop-tauri-nightly.svg --output src-tauri/icons/nightly --ios-color \\\"#000000\\\" && tsx scripts/rebuild-macos-icon.ts\",\n    \"dev:native\": \"expo start --dev-client\",\n    \"android\": \"expo run:android\",\n    \"ios\": \"expo run:ios\",\n    \"build:native\": \"expo export --platform android --output-dir .temp/native-android-export\",\n    \"build:ios\": \"expo export --platform ios --output-dir .temp/native-ios-export\",\n    \"prebuild:native\": \"expo prebuild --platform android --no-install\",\n    \"prebuild:ios\": \"expo prebuild --platform ios --no-install\",\n    \"test:native\"