      "content": "{\n  \"engines\": {\n    \"dsh\": {\n      \"recommend\": \"0.2.1-rc.2\",\n      \"minimum\": \"0.1.7-rc.1\"\n    },\n    \"node\": {\n      \"version\": \">=22.22.0\"\n    },\n    \"pnpm\": {\n      \"version\": \">=11.7.0\",\n      \"sha256\": \"deafa7ec98a1218b6a047289b92fbe2395c1e22d3495bb711653013218ee15ee\"\n    },\n    \"git\": {\n      \"version\": \">2.53.0.2\",\n      \"sha256\": {\n        \"x64\": \"d4bf83d6a860ccae9af44e508e1e00a39f09db6fa78a9ba5543b94d87ca22a29\",\n        \"arm64\": \"842d50edc6bbcf39693e60a8ebb9dabb89b96b932b63aae12d218522b3e497f3\"\n      }\n    }\n  },\n  \"dependencies\": {\n    // 依赖映射规范：AppData 的 dependencies.json 只记录每个依赖的安装根\n    // （null = 用系统环境）；入口相对路径与默认托管根以本表为准。\n    // managedRoot / 映射值支持三种形态：\n    //   $AppData/...    AppData 数据目录（debug 构建为 <base>/dev 的同级）\n    //   $Resources/...  安装包资源目录（`resources/...` 为等价旧写法）\n    //   绝对路径         任意位置（如加载本地捆绑版内核）\n    \"node\": {\n      \"engine\": \">=22.22.0\",\n      \"entry\": {\n        \"windows\": \"node.exe\",\n        \"default\": \"bin/node\"\n      },\n      \"managedRoot\": \"$AppData/runtime\",\n      \"overridable\": true\n    },\n    \"pnpm\": {\n      \"engine\": \">=11.7.0\",\n      \"entry\": \"bin/pnpm.cjs\",\n      \"managedRoot\": \"$AppData/dependencies/pnpm\",\n      \"overridable\": true\n    },\n    \"dsh\": {\n      \"engine\": {\n        \"recommend\": \"0.2.1-rc.2\",\n        \"minimum\": \"0.1.7-rc.1\"\n      },\n      \"entry\": \"node_modules/@deepseek-ai/dsh/lib/bin.js\",\n      \"managedRoot\": \"$AppData/dependencies/dsh\",\n      \"overridable\": true\n    },\n    \"git\": {\n      \"engine\": \">2.53.0.2\",\n      \"entry\": {\n        \"windows\": \"cmd/git.exe\",\n        \"default\": \"bin/git\"\n      },\n      \"managedRoot\": \"$AppData/dependencies/git\",\n      \"overridable\": true\n    }\n  },\n  \"plugins\": {\n    \"depercated\": [\n      \"dsh-win-terminal-inspector\",\n      \"dsh-session-context-menu\",\n      \"dsh-tauri-model-config\",\n      \"dsh-tauri-taiwindcss\",\n      \"dsh-tauri-session\",\n      \"dsh-tauri-ssh\",\n      \"dsh-tauri-panel\",\n      \"dsh-tauri-panel-extension\",\n      \"dsh-tauri-panel-scheduler\",\n      \"dsh-tauri-ssh-ui\",\n      \"dsh-tauri-turnrewind\",\n      \"dsh-tauri-connection\",\n      \"dsh-tauri-bridge\",\n      \"dsh-tauri-running-changes\",\n      \"dsh-tauri-kernel\"\n    ],\n    \"built-in\": [\n      {\n        \"id\": \"dsh-tauri\",\n        \"spec\": \"dsh-tauri\",\n        \"name\": \"DSH Tauri\",\n        \"repo\": \"https://github.com/dsh-tauri-desk/dsh-tauri-plugins/tree/main/packages/dsh-tauri\"\n      },\n      {\n        \"id\": \"dsh-tauri-ui\",\n        \"spec\": \"dsh-tauri-ui\",\n        \"name\": \"DSH Tauri UI\",\n        \"repo\": \"https://github.com/dsh-tauri-desk/dsh-tauri-plugins/tree/main/packages/dsh-tauri-ui\"\n      },\n      {\n        \"id\": \"dsh-tauri-mobile-ui\",\n        \"spec\": \"dsh-tauri-mobile-ui\",\n        \"name\": \"DSH Tauri Mobile UI\",\n        \"repo\": \"https://github.com/dsh-tauri-desk/deepseek-harness-desktop/tree/main/packages/dsh-tauri-mobile-ui\"\n      },\n      {\n        \"id\": \"dsh-tauri-worktree\",\n        \"spec\": \"dsh-tauri-worktree\",\n        \"name\": \"DSH Tauri Worktree\",\n        \"repo\": \"https://github.com/dsh-tauri-desk/dsh-tauri-plugins/tree/main/packages/dsh-tauri-worktree\"\n      },\n      {\n        \"id\": \"dsh-tauri-extension\",\n        \"spec\": \"dsh-tauri-extension\",\n        \"name\": \"DSH Tauri Extension\",\n        \"repo\": \"https://github.com/dsh-tauri-desk/dsh-tauri-plugins/tree/main/packages/dsh-tauri-extension\"\n      },\n      {\n        \"id\": \"dsh-tauri-scheduler\",\n        \"spec\": \"dsh-tauri-scheduler\",\n        \"name\": \"DSH Tauri Scheduler\",\n        \"repo\": \"https://github.com/dsh-tauri-desk/deepseek-harness-desktop/tree/main/packages/dsh-tauri-scheduler\"\n      },\n      {\n        \"id\": \"dsh-tauri-archive\",\n        \"spec\": \"dsh-tauri-archive\",\n        \"name\": \"DSH Tauri Archive\",\n        \"repo\": \"https://github.com/dsh-tauri-desk/dsh-tauri-plugins/tree/main/packages/dsh-tauri-archive\"\n      },\n      {\n        \"id\": \"dsh-tauri-pet\",\n        \"spec\": \"dsh-tauri-pet\",\n        \"name\": \"DSH Tauri Pet\",\n        \"repo\": \"https://github.com/dsh-tauri-desk/deepseek-harness-desktop/tree/main/packages/dsh-tauri-pet\"\n      },\n      {\n        \"id\": \"dsh-tauri-rightclick\",\n        \"spec\": \"dsh-tauri-rightclick\",\n        \"name\": \"DSH Tauri Rightclick Menu\",\n        \"repo\": \"https://github.com/dsh-tauri-desk/dsh-tauri-plugins/tree/main/packages/dsh-tauri-rightclick\"\n      },\n      {\n        \"id\": \"dsh-tauri-model\",\n        \"spec\": \"dsh-tauri-model\",\n        \"name\": \"DSH Tauri Model\",\n        \"repo\": \"https://github.com/dsh-tauri-desk/dsh-tauri-plugins/tree/main/packages/dsh-tauri-model\"\n      },\n      {\n        \"id\": \"dsh-tauri-remote\",\n        \"spec\": \"dsh-tauri-remote\",\n        \"name\": \"DSH Tauri Remote\",\n        \"repo\": \"https://github.com/dsh-tauri-desk/deepseek-harness-desktop/tree/main/packages/dsh-tauri-remote\"\n      },\n      {\n        \"id\": \"dsh-tauri-notification\",\n        \"spec\": \"dsh-tauri-notification\",\n        \"name\": \"DSH Tauri Notification\",\n        \"repo\": \"https://github.com/dsh-tauri-desk/deepseek-harness-desktop/tree/main/packages/dsh-tauri-notification\"\n      }\n    ],\n    \"preset\": [\n      {\n        \"id\": \"dsh-better-sidebar\",\n        \"spec\": \"dsh-better-sidebar\",\n        \"name\": \"DSH Better Sidebar\",\n        \"description\": \"开放的侧边栏底座，支持三方拓展注册新侧边栏页面。内置文件渲染编辑/终端/侧边对话/Git/子代理页面 ｜ Open sidebar foundation, supports third-party extensions to register new sidebar pages. Built-in file rendering/editing, terminal, side chat, Git, and sub-agent pages.\",\n        \"repo\": \"https://github.com/omdsh-dev/DSH-better-sidebar\",\n        \"recommended\": true,\n        \"checked\": true,\n        \"version\": [\n          {\n            \"version\": \"^0.21.1\",\n            \"dsh\": \"^0.1.7-rc.1\"\n          },\n          {\n            \"version\": \"latest\",\n            \"dsh\": \"^0.2.0-rc.1\"\n          }\n        ]\n      },\n      {\n        \"id\": \"dsh-rewind-plugin\",\n        \"spec\": \"dsh-rewind-plugin\",\n        \"name\": \"DSH Rewind\",\n        \"description\": \"便捷无感的同窗口内对话回退，从不新建分支；自带轻量工作区备份，可一并还原文件（Claude Code /rewind 语义）。 · DSH plugin: effortless in-window conversation rewind — never forking a new session; ships a lightweight workspace backup that restores files together with the rewind (Claude Code /rewind semantics).\",\n        \"repo\": \"https://github.com/SiriLee/dsh-rewind\",\n        \"recommended\": true,\n        \"checked\": true,\n        \"version\": [\n          {\n            \"version\": \"^0.14.0\",\n            \"dsh\": \"^0.1.7-rc.1\"\n          },\n          {\n            \"version\": \"latest\",\n            \"dsh\": \"^0.2.0-rc.1\"\n          }\n        ]\n      },\n      {\n        \"id\": \"billion-context\",\n        \"spec\": \"billion-context\",\n        \"name\": \"Billion Context\",\n        \"description\": \"基本稳定可用。上下文压缩插件，兼顾小窗口（100K 上下文足矣）、节省 Token（用量减少至约五分之一）和超长会话（数月级别、几十亿 Token 单会话）。 ｜ A context-compression plugin for small context windows (a 100K context is enough), token savings (5x fewer tokens), and month-long single sessions (billions of tokens). billion-context is all you need\",\n        \"repo\": \"https://github.com/ranxianglei/billion-context\",\n        \"recommended\": true,\n        \"checked\": false,\n        \"version\": \"latest\"\n      },\n      {\n        \"id\": \"dsh-office-kit\",\n        \"spec\": \"dsh-office-kit\",\n        \"name\": \"DSH Office Kit\",\n        \"description\": \"Office documents, PDF, presentations, and spreadsheets for DeepSeek Harness\",\n        \"repo\": \"https://github.com/hairyf/dsh-office-kit\",\n        \"recommended\": true,\n        \"checked\": false,\n        \"version\": [\n          {\n            \"version\": \"latest\",\n            \"dsh\": \"^0.2.1-rc.1\"\n          }\n        ]\n      },\n      {\n        \"id\": \"dsh-ops\",\n        \"spec\": \"dsh-ops\",\n        \"name\": \"DSH Optimize\",\n        \"description\": \"dsh-ops 底层操作工具插件，旨在减少 Token 消耗与任务耗时。 ｜ A toolkit for low-level operations in DSH, designed to reduce token usage and task execution time.\",\n        \"repo\": \"https://github.com/T-Auto/dsh-ops\",\n        \"recommended\": true,\n        \"checked\": false,\n        \"version\": \"latest\"\n      },\n      {\n        \"id\": \"dshmarket\",\n        \"spec\": \"dshmarket\",\n        \"name\": \"DSH Market\",\n        \"repo\": \"https://github.com/dsh-market/dsh-market\",\n        \"description\": \"The plugin market inside DeepSeek Harness — browse, search, one-click install · DSH 可视化插件市场\",\n        \"recommended\": false,\n        \"checked\": false,\n        \"version\": \"latest\"\n      },\n      {\n        \"id\": \"@xmanrui/dsh-im\",\n        \"spec\": \"@xmanrui/dsh-im\",\n        \"name\": \"DSH IM\",\n        \"description\": \"通过扫码或机器人凭据把IM机器人接入DeepSeek Harness（支持飞书、微信、钉钉、企业微信、QQ、Slack、Telegram、Discord和WhatsApp）。 Connect IM bots to DeepSeek Harness via QR code or credentials (9 channels).\",\n        \"repo\": \"https://github.com/xmanrui/dsh-im\",\n        \"recommended\": false,\n        \"checked\": false,\n        \"version\": [\n          {\n            \"version\": \"^4.29.0\",\n            \"dsh\": \"^0.1.7-rc.1\"\n          },\n          {\n            \"version\": \"latest\",\n            \"dsh\": \"^0.2.0-rc.1\"\n          }\n        ]\n      },\n      {\n        \"id\": \"@changfenhuang/dsh-genui\",\n        \"spec\": \"@changfenhuang/dsh-genui\",\n        \"name\": \"DSH GenUI\",\n        \"description\": \"交互式界面插件，通过 dsh-ui 代码块在助手回复中直接呈现布局、图表、绘图、表单、测验、Mermaid 和 3D 场景，并将交互事件回传模型。内含宿主插件、浏览器渲染器和 genui 技能。 ｜ GenUI for DeepSeek Harness: interactive UI components rendered inline in assistant replies via the dsh-ui fence — layout, charts, plots, forms, quizzes, mermaid, 3D scenes, and an action event loop back to the model. Ships the fence-teaching host plugin, the browser renderer (client half), and the genui skill.\",\n        \"repo\": \"https://github.com/omdsh-dev/dsh-genui\",\n        \"recommended\": false,\n        \"checked\": false,\n        \"version\": \"latest\"\n      },\n      {\n        \"id\": \"dsh-context\",\n        \"spec\": \"dsh-context\",\n        \"name\": \"DSH Context\",\n        \"description\": \"一站式 DeepSeek Harness 上下文可视化插件，Context 面板及浏览器和侧边栏与 Context 命令，透视上下文组成、演进、压缩、剪枝等事件与动作。 ｜ The best DeepSeek Harness plugin for context insight and management, with context dashboard / browser / sidebar and context command, for context statistics, composition, breakdown, evolution details, understanding how the context is made of, and how it evolves.\",\n        \"repo\": \"https://github.com/bowenliang123/dsh-context\",\n        \"recommended\": false,\n        \"checked\": false,\n        \"version\": \"latest\"\n      }\n    ]\n  },\n  \"pets\": {\n    \"built-in\": [\n      {\n        \"id\": \"maid-deepseek-whale\",\n        \"name\": \"Maid DeepSeek Whale\",\n        \"desc\": \"一只小小的迷你蓝头发的鲸鱼女仆，穿着海军蓝裙子，白色褶边，蓝眼睛，侧鳍和鲸鱼尾巴。\",\n        \"image\": \"https://raw.githubusercontent.com/PC2005-cloud/dsh-pet/e1ff8c1e4001878cbb80441262d530e16541f138/dsh-pet/assets/preview/daiji-huxi-xiuxian.gif\",\n        \"kind\": \"dsh\",\n        \"size\": 220,\n        \"config\": \"https://raw.githubusercontent.com/PC2005-cloud/dsh-pet/e1ff8c1e4001878cbb80441262d530e16541f138/dsh-pet/assets/config.jsonc\",\n        \"uri\": {\n          \"default\": \"https://raw.githubusercontent.com/PC2005-cloud/dsh-pet/e1ff8c1e4001878cbb80441262d530e16541f138/dsh-pet/assets/webm\",\n          \"mac\": \"https://raw.githubusercontent.com/dsh-tauri-desk/dsh-pet-mov/be0f3bb494cb71a4c73f916c0b92d25a3ab4d002/mov\"\n        },\n        \"ext\": {\n          \"default\": \"webm\",\n          \"mac\": \"mov\"\n        }\n      },\n      {\n        \"id\": \"dsh-chan-sticker-pet\",\n        \"name\": \"Maid DeepSeek Sticker\",\n        \"desc\": \"157 个贴纸动作与透明待机动画。\",\n        \"image\": \"https://raw.githubusercontent.com/hairyf/dsh-pet-sticker/6634e0de9cace37ac6b747a960c833209ad015a3/preview/preview.gif\",\n        \"kind\": \"dsh\",\n        \"size\": 220,\n        \"config\": \"https://raw.githubusercontent.com/hairyf/dsh-pet-sticker/6634e0de9cace37ac6b747a960c833209ad015a3/config.jsonc\",\n        \"uri\": {\n          \"default\": \"https://raw.githubusercontent.com/hairyf/dsh-pet-sticker/6634e0de9cace37ac6b747a960c833209ad015a3/webm\",\n          \"mac\": \"https://raw.githubusercontent.com/hairyf/dsh-pet-sticker/6634e0de9cace37ac6b747a960c833209ad015a3/mov\"\n        },\n        \"ext\": {\n          \"default\": \"webm\",\n          \"mac\": \"mov\"\n        }\n      }\n    ]\n  }\n}\n"
